import * as React from 'react';
import Button from '@tecton-mui/ui/Button';
import Dialog from '@tecton-mui/ui/Dialog';
import DialogActions from '@tecton-mui/ui/DialogActions';
import DialogContent from '@tecton-mui/ui/DialogContent';
import DialogContentText from '@tecton-mui/ui/DialogContentText';
import DialogTitle from '@tecton-mui/ui/DialogTitle';
import Snackbar from '@tecton-mui/ui/Snackbar';
import type { SnackbarCloseReason } from '@tecton-mui/ui/Snackbar';

export default function DialogSnackbar() {
  const [dialogOpen, setDialogOpen] = React.useState(false);
  const [snackbarOpen, setSnackbarOpen] = React.useState(false);

  const handleDialogClose = () => {
    setDialogOpen(false);
    setSnackbarOpen(false);
  };

  const handleSnackbarClose = (
    _event: React.SyntheticEvent | Event,
    reason: SnackbarCloseReason,
  ) => {
    if (reason === 'clickaway') {
      return;
    }
    setSnackbarOpen(false);
  };

  return (
    <React.Fragment>
      <Button onClick={() => setDialogOpen(true)}>Open dialog</Button>
      <Dialog
        open={dialogOpen}
        onClose={(_event, reason) => {
          if (reason === 'escapeKeyDown' && snackbarOpen) {
            setSnackbarOpen(false);
            return;
          }
          handleDialogClose();
        }}
        aria-labelledby="snackbar-dialog-title"
        aria-describedby="snackbar-dialog-description"
      >
        <DialogTitle id="snackbar-dialog-title">Snackbar in a dialog</DialogTitle>
        <DialogContent>
          <DialogContentText id="snackbar-dialog-description">
            Show the snackbar, then press Escape to close it. Press Escape again to
            close the dialog.
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleDialogClose}>Close</Button>
          <Button onClick={() => setSnackbarOpen(true)}>Show snackbar</Button>
        </DialogActions>
        <Snackbar
          open={snackbarOpen}
          onClose={handleSnackbarClose}
          message="Press Escape to close this snackbar"
        />
      </Dialog>
    </React.Fragment>
  );
}
